(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.019-t*0.27)*18 + Math.sin(x*0.016+t*0.33)*12;
  const w2x = Math.sin((x+w1x)*0.025-t*0.15)*8;
  const w2y = Math.cos((y+w1y)*0.022+t*0.18)*8;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 1],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 2],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1, 0],
    [400+Math.cos(t*0.55+2)*60, 220+Math.sin(t*0.75)*40, 0.13, 1.8, 1],
    [200+Math.sin(t*0.25)*110, 60+Math.cos(t*0.45+3)*70, 0.075, 2.4, 2]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for (const [sX,sY,f,sp,layer] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave = Math.sin(d*f - t*sp);
    const wave2 = Math.sin(d*f*1.618 + t*sp*0.618);
    if (layer===0) { aS += wave; iS += Math.sin(d*f*0.7+t*sp*0.6+1.5); }
    else if (layer===1) { aS += wave*0.7; iS2 += Math.sin(d*f*0.8-t*sp*0.5+2.0)*0.8; aS2 += wave2*0.6; }
    else { iS += wave*0.5; aS2 += Math.sin(d*f*0.6+t*sp*0.4+0.8)*0.7; iS2 += wave2*0.5; }
  }
  aS/=9; iS/=9; aS2/=9; iS2/=9;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2 = Math.sin(dist*0.08+ang*5-t*2.0)*0.2;
  const cross = Math.sin(sx*0.07)*Math.sin(sy*0.07)*0.3;
  const micro = Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.5)*0.15;
  const react1 = Math.tanh((aS - iS*0.7 + bg*0.3 + spiral)*2.2);
  const react2 = Math.tanh((aS2 - iS2*0.6 + spiral2 + cross)*2.5);
  const coupled = Math.tanh(react1*0.65 + react2*0.35 + micro)*0.85 + micro*0.15;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.2;
  const edge = 1.0/(1.0+Math.exp(-8*(Math.abs(coupled)-0.5)))*0.3;
  const blend = coupled*0.7 + cell*0.1 + edge, v = blend*0.5+0.5;
  const pal = [
    [5,10,45],[10,35,85],[12,65,115],[18,110,135],[45,155,145],
    [140,185,120],[210,195,80],[230,150,65],[210,100,75],[175,60,80],
    [120,35,70],[60,18,55],[20,10,40],[5,10,45]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.85+Math.sin(coupled*Math.PI)*0.15;
  const glow = Math.max(0, coupled)*0.12;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum + glow*80)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum + glow*60)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum + glow*40)|0)
  ];
}
